using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Globalization;
namespace V15Voice {public partial class MainForm {
 CheckBox textTargetEnabled=new CheckBox();TextBox textTargetValue=new TextBox();NumericUpDown textTargetChange=new NumericUpDown();Label textTargetInfo=new StudioMessageLabel();bool targetBuilt,settingTarget;double? targetCalibration;string targetCalibrationKey="",targetResultKey="";TextTargetResult lastTextTarget;
 string TargetKey(){return SpeechArchive.Hash((voices.SelectedItem==null?"":((VoiceItem)voices.SelectedItem).Key)+"|"+speed.Value+"|"+punctuationMode.SelectedIndex+"|"+commaPause.Value+"|"+stopPause.Value+"|"+questionPause.Value+"|"+paragraphPause.Value+"|"+gap.Value+"|"+breathMode.SelectedIndex+"|"+breathEvery.Value+"|"+breathPath.Text+"|"+"|"+TwoSpeakers+"|"+SecondKey()+"|"+String.Join("\n",cues.Select(c=>c.Speaker+"|"+c.Text)));}
 void BuildTextTargetControls(FlowLayoutPanel parent){textTargetEnabled.Text="Căn TXT theo thời lượng đích";textTargetEnabled.AutoSize=true;textTargetEnabled.MaximumSize=new Size(350,0);parent.Controls.Add(textTargetEnabled);
  var row=new TableLayoutPanel{Width=350,Height=60,ColumnCount=2,RowCount=2,Margin=new Padding(0,4,0,4)};row.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,65));row.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,35));row.RowStyles.Add(new RowStyle(SizeType.Absolute,26));row.RowStyles.Add(new RowStyle(SizeType.Percent,100));row.Controls.Add(new Label{Text="Đích: giây / mm:ss",Dock=DockStyle.Fill,ForeColor=muted},0,0);row.Controls.Add(new Label{Text="Căn tối đa ± %",Dock=DockStyle.Fill,ForeColor=muted},1,0);
  textTargetValue.Dock=DockStyle.Fill;textTargetValue.Margin=new Padding(0,0,8,0);textTargetValue.Font=new Font("Segoe UI",11);row.Controls.Add(textTargetValue,0,1);textTargetChange.Minimum=1;textTargetChange.Maximum=25;textTargetChange.Value=10;textTargetChange.Increment=1;textTargetChange.DecimalPlaces=0;textTargetChange.Dock=DockStyle.Fill;textTargetChange.Margin=new Padding(0);row.Controls.Add(textTargetChange,1,1);parent.Controls.Add(row);
  textTargetInfo.AutoSize=true;textTargetInfo.MaximumSize=new Size(350,0);textTargetInfo.ForeColor=muted;AddStudioMessage(parent,textTargetInfo,116);AddLabel(parent,"Không thêm im lặng dài hoặc cắt lời. Đích TXT trong hàng đợi đặt riêng từng file.",false);targetBuilt=true;
  textTargetEnabled.CheckedChanged+=(s,e)=>TargetInputChanged();textTargetValue.TextChanged+=(s,e)=>TargetInputChanged();textTargetChange.ValueChanged+=(s,e)=>TargetInputChanged();
  foreach(var c in new Control[]{fitMode,minSpeed,maxSpeed}){var cb=c as ComboBox;if(cb!=null)cb.SelectedIndexChanged+=(s,e)=>RefreshTextTarget();var n=c as NumericUpDown;if(n!=null)n.ValueChanged+=(s,e)=>RefreshTextTarget();}RefreshTextTarget();
 }
 void SetTextTargetUI(double seconds){settingTarget=true;try{textTargetEnabled.Checked=seconds>0;textTargetValue.Text=seconds>0?Scripts.Stamp(seconds):"";lastTextTarget=null;}finally{settingTarget=false;}RefreshTextTarget();}
 void SetJobTarget(BatchJob job,double seconds){if(job.Timed&&seconds!=0)throw new Exception("SRT dùng timeline nguồn; đích riêng chỉ cho TXT.");if(seconds!=0)TextTargetVoice.ValidateSeconds(seconds);if(job.TargetSeconds==seconds)return;job.TargetSeconds=seconds;job.State=JobState.Queued;job.OutputPath=job.Error=job.Warning=job.TimelineReport="";job.AudioDuration=0;job.DurationFinal=false;SaveQueueIfChanged();}
 void TargetInputChanged(){if(!targetBuilt||settingTarget||restoring||busy)return;lastTextTarget=null;lastOutput=null;openOutput.Enabled=false;readingLive=false;RefreshQualityEnabled();RefreshProse();if(editingJob!=null&&!editingJob.Timed){try{SetJobTarget(editingJob,textTargetEnabled.Checked?TextTargetVoice.Parse(textTargetValue.Text):0);}catch{}RefreshJobs();}UpdateShared();SaveSession();}
 void AddTextTargetOptions(RenderOptions o,bool include){o.TargetChange=(double)textTargetChange.Value/100;o.TargetSeconds=0;o.TargetRaw="";if(include&&o.Prose&&textTargetEnabled.Checked){o.TargetRaw=textTargetValue.Text;o.TargetSeconds=TextTargetVoice.Parse(textTargetValue.Text);TextTargetVoice.Validate(o);}}
 void RefreshTextTarget(){if(!targetBuilt)return;bool enabled=proseInput&&textTargetEnabled.Checked;if(proseTiming.Parent!=null)proseTiming.Parent.Visible=!enabled||busy;textTargetValue.Enabled=!busy&&enabled;textTargetChange.Enabled=!busy&&proseInput;if(!enabled){textTargetInfo.Text="TXT đọc tự nhiên; chưa đặt thời lượng đích.";textTargetInfo.ForeColor=muted;return;}try{double target=TextTargetVoice.Parse(textTargetValue.Text);var o=new RenderOptions{BaseSpeed=(double)speed.Value,MinSpeed=(double)minSpeed.Value,MaxSpeed=(double)maxSpeed.Value,GentleFit=fitMode.SelectedIndex==0,TargetChange=(double)textTargetChange.Value/100};double min=TextTargetVoice.Minimum(o),max=TextTargetVoice.Maximum(o);string key=TargetKey();if(lastTextTarget!=null&&targetResultKey==key&&Math.Abs(lastTextTarget.Target-target)<.0005){textTargetInfo.Text=lastTextTarget.Describe()+(lastTextTarget.Measured.HasValue?"\r\nLần căn cuối dư/thiếu: "+(lastTextTarget.Measured.Value-target).ToString("+0.000;-0.000;0",CultureInfo.InvariantCulture)+"s":"")+(lastTextTarget.Reason.Length>0?"\r\n"+lastTextTarget.Reason:"");textTargetInfo.ForeColor=lastTextTarget.Complete?teal:Color.DarkOrange;return;}
   double estimate=targetCalibration.HasValue&&targetCalibrationKey==key?targetCalibration.Value:cues.Sum(c=>c.Words)/(2.5*(double)speed.Value);bool measured=targetCalibration.HasValue&&targetCalibrationKey==key;double required=(double)speed.Value*estimate/target;string warning=required>max?"Dự kiến lời dài hơn khung; nên rút gọn.":required<min?"Dự kiến lời ngắn hơn khung; nên bổ sung nội dung hoặc giảm đích.":"Dự kiến có thể căn trong giới hạn; cần render để xác nhận.";textTargetInfo.Text="Đích "+Scripts.Stamp(target)+"\r\n"+(measured?"Ước lượng từ mẫu giọng: ":"Ước lượng sơ bộ chưa đo giọng: ")+Scripts.Stamp(estimate)+"\r\nGiới hạn áp dụng: "+min.ToString("0.000")+"–"+max.ToString("0.000")+"x\r\n"+warning;textTargetInfo.ForeColor=required>max||required<min?Color.DarkOrange:teal;
  }catch(Exception e){textTargetInfo.Text=e.Message;textTargetInfo.ForeColor=Color.Firebrick;}}
 void CaptureTargetResult(RenderOptions o){if(o==null||o.TargetResult==null)return;lastTextTarget=o.TargetResult;targetResultKey=TargetKey();if(lastTextTarget.Natural.HasValue){targetCalibration=lastTextTarget.Natural;targetCalibrationKey=targetResultKey;}RefreshTextTarget();}
 void SetQueuedTextTarget(){if(busy||jobGrid.CurrentRow==null)return;var j=jobs[jobGrid.CurrentRow.Index];if(j.Timed||j.State==JobState.ImportFailed){status.Text="Chỉ đặt đích cho TXT đã nhập được; SRT dùng timeline nguồn.";return;}using(var f=new Form{Text="Thời lượng đích TXT · "+j.Name,Size=new Size(540,230),StartPosition=FormStartPosition.CenterParent}){var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),FlowDirection=FlowDirection.TopDown,WrapContents=false};var field=new TextBox{Width=470,Text=j.TargetSeconds>0?Scripts.Stamp(j.TargetSeconds):""};flow.Controls.Add(new Label{Text="Nhập giây / mm:ss / hh:mm:ss. Để trống = đọc tự nhiên.",AutoSize=true});flow.Controls.Add(field);var info=new Label{AutoSize=true,MaximumSize=new Size(470,0),ForeColor=Color.Firebrick};flow.Controls.Add(info);flow.Controls.Add(Btn("Lưu đích cho file này",(s,e)=>{try{double target=TextTargetVoice.Parse(field.Text,true);SetJobTarget(j,target);if(editingJob==j)SetTextTargetUI(target);f.DialogResult=DialogResult.OK;f.Close();RefreshJobs();}catch(Exception x){info.Text=x.Message;}}));f.Controls.Add(flow);f.ShowDialog(this);}}
}}
